/* @autogenerated */
import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRoute, provideRouter, Router } from '@angular/router';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { BehaviorSubject, of } from 'rxjs';
import { UnauthorizedComponent } from './unauthorized.component';
import { AppStateService } from '@shared/context/state/app-state.service';
import { IdentityService } from '@shared/context/identity/identity.service';
import { UserInfo } from '@shared/context/identity/user-info.model';
import { AuthorizationAccessService } from './authorization-access.service';

describe('UnauthorizedComponent', () => {
  function setup(params: Record<string, string>, user: UserInfo) {
    const route = {
      snapshot: { queryParamMap: { get: (key: string) => params[key] ?? null } },
    };
    const user$ = new BehaviorSubject<UserInfo>(user);
    const state = { language: signal('es'), tenant: signal('main'), user$: () => user$ };
    const identity = { login: jasmine.createSpy('login'), logout: jasmine.createSpy('logout') };
    const access = { remember: jasmine.createSpy('remember') };

    TestBed.configureTestingModule({
      imports: [UnauthorizedComponent, TranslocoTestingModule.forRoot({ langs: {} })],
      providers: [
        provideRouter([]),
        { provide: ActivatedRoute, useValue: route },
        { provide: AppStateService, useValue: state },
        { provide: IdentityService, useValue: identity },
        { provide: AuthorizationAccessService, useValue: access },
      ],
    });

    const router = TestBed.inject(Router);
    spyOn(router, 'navigateByUrl').and.resolveTo(true);
    spyOn(router, 'navigate').and.resolveTo(true);
    const fixture = TestBed.createComponent(UnauthorizedComponent);
    fixture.detectChanges();
    const buttons = () => Array.from(fixture.nativeElement.querySelectorAll('button')) as HTMLButtonElement[];
    return { fixture, router, user$, identity, access, buttons };
  }

  it('redirects to returnUrl when the user signs in', () => {
    const { router, user$ } = setup({ returnUrl: '/target', reason: '401' }, { authenticated: false });
    expect(router.navigateByUrl).not.toHaveBeenCalled();

    user$.next({ authenticated: true });

    expect(router.navigateByUrl).toHaveBeenCalledWith('/target');
  });

  it('redirects to language and tenant when authenticated without returnUrl', () => {
    const { router } = setup({}, { authenticated: true });

    expect(router.navigate).toHaveBeenCalledWith(['es', 'main']);
  });

  it('with reason=401 offers sign in and remembers the requested page', () => {
    const { identity, access, buttons } = setup({ returnUrl: '/target', reason: '401' }, { authenticated: false });

    expect(buttons().length).toBe(1);
    buttons()[0].click();

    expect(access.remember).toHaveBeenCalledWith('/target');
    expect(identity.login).toHaveBeenCalledWith('main');
  });

  it('with reason=403 does not loop back and offers home and switch account', () => {
    const { fixture, router, identity, buttons } = setup(
      { returnUrl: '/target', reason: '403' },
      { authenticated: true },
    );

    expect(router.navigateByUrl).not.toHaveBeenCalled();
    expect(fixture.nativeElement.querySelector('a').getAttribute('href')).toBe('/es/main');
    expect(buttons().length).toBe(1);

    buttons()[0].click();
    expect(identity.logout).toHaveBeenCalledWith('main');
  });

  it('shows the 401 image and no home link', () => {
    const { fixture } = setup({ reason: '401' }, { authenticated: false });

    expect(fixture.nativeElement.querySelector('img').getAttribute('src')).toContain('error-401.png');
    expect(fixture.nativeElement.querySelector('a')).toBeNull();
  });
});
